const SHOP={phone:"+919848318801",displayPhone:"+91 98483 18801",address:"H. No 4, Pick N Eat (Amul Icecreams), Santhosh Nagar, Prajasai Garden Road, Plot No 9, 48/10, Bandlaguda Rd, Telangana 501303, India",maps:"https://maps.app.goo.gl/xwJEqc8thWthagxH7?g_st=iw"};

const grid=document.getElementById('productGrid');const filters=document.getElementById('filters');const search=document.getElementById('search');const count=document.getElementById('count');const empty=document.getElementById('empty');const nav=document.getElementById('nav');const menuBtn=document.getElementById('menuBtn');let active='All';
const money=n=>`₹${Number(n).toLocaleString('en-IN')}`;
const cats=['All',...new Set(PRODUCTS.map(p=>p.category))];
filters.innerHTML=cats.map(c=>`<button class="filter ${c==='All'?'active':''}" data-cat="${c}">${c}</button>`).join('');
filters.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{active=b.dataset.cat;filters.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render();});
search.addEventListener('input',render);menuBtn.addEventListener('click',()=>nav.classList.toggle('open'));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')));
function card(p){const [x,y,w,h]=p.crop;const bg=PAGE_IMAGES[String(p.page)];const bw=(917/w*100).toFixed(2);const bh=(1728/h*100).toFixed(2);const bx=(-x/w*100).toFixed(2);const by=(-y/h*100).toFixed(2);return `<article class="product-card"><div class="photo crop" style="background-image:url('${bg}');background-size:${bw}% ${bh}%;background-position:${bx}% ${by}%;" role="img" aria-label="${p.name} ${p.size}"></div><div class="product-body"><span class="category">${p.category}</span><h3>${p.name}</h3><div class="size">${p.size}</div><div class="price">${money(p.price)}</div><button class="add" data-name="${encodeURIComponent(p.name)}">Add to Pick</button></div></article>`}
function render(){const q=search.value.trim().toLowerCase();const list=PRODUCTS.filter(p=>(active==='All'||p.category===active)&&(!q||`${p.name} ${p.category} ${p.size}`.toLowerCase().includes(q)));count.textContent=list.length===PRODUCTS.length?PRODUCTS.length:list.length;empty.hidden=list.length>0;grid.innerHTML=list.map(card).join('');grid.querySelectorAll('.add').forEach(b=>b.onclick=()=>openOrder(decodeURIComponent(b.dataset.name)));}
function openOrder(name){document.getElementById('orderTitle').textContent=name;document.getElementById('orderModal').classList.add('show');document.getElementById('wa').href=`https://wa.me/${SHOP.phone.replace('+','')}?text=${encodeURIComponent("Hi Pick'N'Eat, I am interested in "+name+".")}`;}
document.getElementById('closeModal').onclick=()=>document.getElementById('orderModal').classList.remove('show');document.getElementById('orderModal').onclick=e=>{if(e.target.id==='orderModal')e.target.classList.remove('show')};document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('phone').textContent=SHOP.displayPhone;document.getElementById('phone').href=`tel:${SHOP.phone}`;document.getElementById('address').textContent=SHOP.address;document.getElementById('mapLink').href=SHOP.maps;render();